extern      INT16U   OS_CPU_IntDisMeasCntsDelta;
extern      INT16U   OS_CPU_IntDisMeasCntsOvrhd;
#endif

extern      OS_STK   OS_CPU_ExceptStk[OS_CPU_EXCEPT_STK_SIZE];
